      if(check.results?.length){const wrap=el('div','table-wrap');const table=el('table','data-table');const tr=el('tr');[t('Case','Cas'),t('Expected','Attendu'),t('Observed','Observé'),t('Result','Résultat')].forEach(label=>append(tr,el('th','',label)));append(table,tr);check.results.forEach(c=>{const row=el('tr');append(row,el('td','',c.case),el('td','code-text',JSON.stringify(c.expected)),el('td','code-text',JSON.stringify(c.actual)),el('td','',c.passed?t('Matches','Concorde'):t('Does not match','Ne concorde pas')));append(table,row);});append(wrap,table);append(block,wrap);}
