    if(result?.comparisons){append(card,el('p','inline-note',result.improvedOutcome?t('Inspect the stated improvement and its scope.','Examinez l’amélioration annoncée et sa portée.'):t('No improved outcome demonstrated. Passing reuse and a better discovery procedure are different claims.','Aucun meilleur résultat démontré. Une réutilisation réussie et une meilleure capacité de découverte sont deux affirmations distinctes.')));}
