  function renderEvidence(){const summary=$('evidence-summary'),box=$('evidence-list');clear(summary);clear(box);const runs=list(project.runs);if(!runs.length){append(box,el('div','empty-text',t('No experiment has been run in this project. Model contributions alone remain UNKNOWN.','Aucune expérience n’a été exécutée dans ce projet. Les contributions seules restent UNKNOWN.')));return;}const metrics=el('div','metrics');[[t('Recorded runs','Exécutions consignées'),runs.length],[t('Inspected sources','Sources consignées'),list(project.sources).length],[t('Retained capabilities','Capacités conservées'),list(project.capabilities).length]].forEach(([label,value])=>{const m=el('div','metric');append(m,el('span','metric-label',label),el('strong','metric-value',value));append(metrics,m);});append(summary,metrics,el('p','inline-note',t('A stored receipt is a record, not fresh verification. Re-run the check after changing inputs or the instrument.','Un reçu enregistré est une trace, pas une nouvelle vérification. Réexécutez les contrôles après toute modification.')));runs.forEach((run,i)=>{const card=summaryResult(run,run.title||run.name||t('Run ','Exécution ')+(i+1));if(run.createdAt||run.timestamp)append(card,el('p','bounded-details',dateText(run.createdAt||run.timestamp)));append(box,card);});}
