      const providerWrap=el('div'),modelWrap=el('div');const providerLabel=el('label','',t('Alternative ','Proposition ')+(index+2)+' · '+t('provider','fournisseur'));const selector=el('select');selector.id='bridge-alternative-provider-'+index;providerLabel.htmlFor=selector.id;fillProviderOptions(selector,selection.provider);selection.provider=selector.value;selector.disabled=bridgeBusy;
      const modelLabel=el('label','',t('Model','Modèle'));const input=el('input');input.id='bridge-alternative-model-'+index;modelLabel.htmlFor=input.id;input.value=selection.model||'';input.autocomplete='off';input.disabled=bridgeBusy;
      selector.addEventListener('change',()=>{selection.provider=selector.value;const configured=bridge.providers.find(p=>p.id===selector.value);selection.model=configured?.models?.[0]||'';input.value=selection.model;});
